 * Cell address handling: parsing, validity, canonicalisation, ordering.
 */

// Strict address shape: 1-2 letters then 1-3 digits, nothing else.
const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

export function colToIndex(letters) {
  let idx = 0
  for (const ch of letters) {
    idx = idx * 26 + (ch.charCodeAt(0) - 64)
  }
  return idx
}

export function indexToCol(idx) {
  let s = ''
  while (idx > 0) {
    const rem = (idx - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    idx = Math.floor((idx - 1) / 26)
  }
  return s
}

/**
 * Parses a raw address string (any case). Returns an object describing
 * whether it has valid address *shape* (letters+digits pattern) and,
 * separately, whether it names a cell inside the addressable range.
 */
export function parseAddressShape(raw) {
  const m = ADDRESS_RE.exec(raw)
  if (!m) return { valid: false }
  const letters = m[1].toUpperCase()
  const digits = m[2]
  const row = parseInt(digits, 10)
  if (row < 1) return { valid: false }
  const col = colToIndex(letters)
  return { valid: true, letters, row, col, canon: letters + String(row) }
}

/** Like parseAddressShape but also accepts word-tokens with zero digits
 * (used from formula word tokens, e.g. "FOO") — those are shape-invalid
 * (outside the addressable range) rather than a grammar failure. The
 * caller is responsible for ensuring the token only contains letters
 * followed by digits. */
export function parseFormulaWordAsAddress(raw) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(raw)
  if (!m) return { valid: false }
  const letters = m[1]
  const digits = m[2]
  if (letters.length < 1 || letters.length > 2) return { valid: false }
  if (digits.length < 1 || digits.length > 3) return { valid: false }
  const row = parseInt(digits, 10)
  if (row < 1) return { valid: false }
  const upper = letters.toUpperCase()
  const col = colToIndex(upper)
  return { valid: true, letters: upper, row, col, canon: upper + String(row) }
}

export function canonToColRow(canon) {
  const m = /^([A-Z]{1,2})([0-9]+)$/.exec(canon)
  return { col: colToIndex(m[1]), row: parseInt(m[2], 10) }
}

export function makeCanon(col, row) {
  return indexToCol(col) + String(row)
}

/** Comparator for canonical addresses: ascending column, then row. */
export function compareAddr(a, b) {
  const ca = canonToColRow(a)
  const cb = canonToColRow(b)
  if (ca.col !== cb.col) return ca.col - cb.col
  return ca.row - cb.row
}
"}

