chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t5/cell-52cru1/src/value.js","content":"/**
 * Tagged runtime values: number, text, bool, error.
 */

export function numVal(v) {
  return { t: 'number', v }
}
export function textVal(v) {
  return { t: 'text', v }
}
export function boolVal(v) {
  return { t: 'bool', v }
}
export function errVal(v) {
  return { t: 'error', v }
}

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

/** Converts a value to a number for arithmetic positions. Booleans become
 * 1/0, text becomes #VALUE!, errors pass through untouched (callers should
 * already have filtered errors before calling this in most cases). */
export function toNumber(value) {
  if (value.t === 'number') return value
  if (value.t === 'bool') return numVal(value.v ? 1 : 0)
  if (value.t === 'text') return errVal('#VALUE!')
  return value // error
}

export function isFiniteResult(n) {
  return Number.isFinite(n)
}

/** Formats a number the way JavaScript would print it after rounding to
 * ten significant digits. */
export function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

export function formatValue(value) {
  switch (value.t) {
    case 'number':
      return formatNumber(value.v)
    case 'text':
      return value.v
    case 'bool':
      return value.v ? 'TRUE' : 'FALSE'
    case 'error':
      return value.v
    default:
      throw new Error('unreachable')
  }
}
"}

