{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t5/cell-52cru1/src/lexer.js","content":"/**
 * Tokenises a formula body (the part after the leading '=').
 */

export class LexError extends Error {}

const MULTI_OPS = ['<=', '>=', '<>']
const SINGLE_OPS = ['^', '*', '/', '+', '-', '=', '<', '>', '(', ')', ':', ',']

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      if (src[j] === '.') {
        let k = j + 1
        let hasDigit = false
        while (k < n && src[k] >= '0' && src[k] <= '9') {
          k++
          hasDigit = true
        }
        if (hasDigit) {
          tokens.push({ type: 'NUMBER', v: src.slice(i, k) })
          i = k
          continue
        }
      }
      tokens.push({ type: 'NUMBER', v: src.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < n && /[A-Za-z]/.test(src[j])) j++
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      tokens.push({ type: 'WORD', v: src.slice(i, j) })
      i = j
      continue
    }
    const two = src.slice(i, i + 2)
    if (MULTI_OPS.includes(two)) {
      tokens.push({ type: 'OP', v: two })
      i += 2
      continue
    }
    if (SINGLE_OPS.includes(ch)) {
      tokens.push({ type: 'OP', v: ch })
      i += 1
      continue
    }
    throw new LexError(`unexpected character ${ch}`)
  }
  return tokens
}
"}

