  if (tok && tok.type === 'OP' && (tok.v === '-' || tok.v === '+')) {
    ts.next()
    const operand = parseUnary(ts)
    return { type: 'UnaryOp', op: tok.v, operand }
  }
  return parsePrimary(ts)
}

function parsePrimary(ts) {
  const tok = ts.peek()
  if (!tok) throw new GrammarError('unexpected end')
  if (tok.type === 'NUMBER') {
    ts.next()
    return { type: 'Num', value: Number(tok.v) }
  }
  if (tok.type === 'OP' && tok.v === '(') {
    ts.next()
    const inner = parseComparison(ts)
    const close = ts.next()
    if (!close || close.type !== 'OP' || close.v !== ')') throw new GrammarError('expected )')
    return inner
  }
