    args.push(parseArg(ts))
    const tok = ts.next()
    if (!tok) throw new GrammarError('unexpected end in call')
    if (tok.type === 'OP' && tok.v === ',') continue
    if (tok.type === 'OP' && tok.v === ')') break
    throw new GrammarError('expected , or )')
  }
  return { type: 'Call', name, args }
