{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t5/cell-52cru1/src/evaluator.js","content":"/**
 * Formula evaluation over a sheet, with cycle detection and per-cell
 * memoisation. Also provides syntactic dependency extraction for `deps`.
 */

import { parseFormula, CALL_NAMES } from './parser.js'
import { parseAddressShape, parseFormulaWordAsAddress, colToIndex, indexToCol, compareAddr } from './address.js'
import { numVal, textVal, boolVal, errVal, toNumber, ERROR_TOKENS, isFiniteResult } from './value.js'

const NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

export function parseLiteral(content) {
  if (content === '') return numVal(0)
  if (NUMBER_RE.test(content)) return numVal(Number(content))
  if (ERROR_TOKENS.includes(content)) return errVal(content)
  return textVal(content)
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells // Map<canon, content>
    this.cache = new Map() // canon -> Value
    this.visiting = new Set()
    this.astCache = new Map() // canon -> AST | null (parsed once)
  }

  getAst(canon, content) {
    if (this.astCache.has(canon)) return this.astCache.get(canon)
    const body = content.slice(1)
    const ast = parseFormula(body)
    this.astCache.set(canon, ast)
    return ast
  }

  evaluateCell(canon) {
    if (this.cache.has(canon)) return this.cache.get(canon)
    if (this.visiting.has(canon)) return errVal('#CYCLE!')

    const content = this.cells.get(canon)
    if (content === undefined) {
      const v = numVal(0)
      this.cache.set(canon, v)
      return v
    }

    let value
    if (content.startsWith('=')) {
      this.visiting.add(canon)
      const ast = this.getAst(canon, content)
      value = ast === null ? errVal('#ERR!') : this.evalNode(ast)
      this.visiting.delete(canon)
    } else {
      value = parseLiteral(content)
    }
    this.cache.set(canon, value)
    return value
  }

  evalAddressWord(raw) {
    const shape = parseFormulaWordAsAddress(raw)
    if (!shape.valid) return errVal('#REF!')
    return this.evaluateCell(shape.canon)
  }

  rangeCells(fromRaw, toRaw) {
    const a = parseFormulaWordAsAddress(fromRaw)
    const b = parseFormulaWordAsAddress(toRaw)
    if (!a.valid || !b.valid) return null
    const minCol = Math.min(a.col, b.col)
    const maxCol = Math.max(a.col, b.col)
    const minRow = Math.min(a.row, b.row)
    const maxRow = Math.max(a.row, b.row)
    const out = []
    for (let col = minCol; col <= maxCol; col++) {
      for (let row = minRow; row <= maxRow; row++) {
        out.push(indexToCol(col) + String(row))
      }
    }
    return out
  }

  /** Expands one call argument node into an array of Values, in order. */
  expandArg(arg) {
    if (arg.type === 'Range') {
      const cells = this.rangeCells(arg.from, arg.to)
      if (cells === null) return [errVal('#REF!')]
      return cells.map((c) => this.evaluateCell(c))
    }
    return [this.evalNode(arg)]
  }

  expandArgs(args) {
    const out = []
    for (const a of args) out.push(...this.expandArg(a))
    return out
  }

  evalNode(node) {
    switch (node.type) {
      case 'Num':
        return numVal(node.value)
      case 'Bool':
        return boolVal(node.value)
      case 'Address':
        return this.evalAddressWord(node.raw)
      case 'UnaryOp':
        return this.evalUnary(node)
      case 'BinOp':
        return this.evalBinOp(node)
      case 'Call':
        return this.evalCall(node)
      default:
        throw new Error('unreachable node type ' + node.type)
    }
  }

  evalUnary(node) {
    const v = this.evalNode(node.operand)
    if (v.t === 'error') return v
    const n = toNumber(v)
    if (n.t === 'error') return n
    const result = node.op === '-' ? -n.v : n.v
    if (!isFiniteResult(result)) return errVal('#DIV/0!')
    return numVal(result)
  }

  evalBinOp(node) {
    const COMPARE = new Set(['=', '<>', '<', '<=', '>', '>='])
    const lv = this.evalNode(node.left)
    const rv = this.evalNode(node.right)
    if (COMPARE.has(node.op)) {
      if (lv.t === 'error') return lv
      if (rv.t === 'error') return rv
      return compareValues(node.op, lv, rv)
    }
    if (lv.t === 'error') return lv
    if (rv.t === 'error') return rv
    const ln = toNumber(lv)
    if (ln.t === 'error') return ln
    const rn = toNumber(rv)
    if (rn.t === 'error') return rn
    if (node.op === '/' && rn.v === 0) return errVal('#DIV/0!')
    let result
    switch (node.op) {
      case '+':
        result = ln.v + rn.v
        break
      case '-':
        result = ln.v - rn.v
        break
      case '*':
        result = ln.v * rn.v
        break
      case '/':
        result = ln.v / rn.v
        break
      case '^':
        result = Math.pow(ln.v, rn.v)
        break
      default:
        throw new Error('unreachable op ' + node.op)
    }
    if (!isFiniteResult(result)) return errVal('#DIV/0!')
    return numVal(result)
  }

  evalCall(node) {
    const name = node.name
    if (!CALL_NAMES.has(name)) return errVal('#NAME?')

    if (name === 'ABS') {
      if (node.args.length !== 1) return errVal('#ERR!')
      const vals = this.expandArg(node.args[0])
      const err = vals.find((v) => v.t === 'error')
      if (err) return err
      const v = vals[0]
      const n = toNumber(v)
      if (n.t === 'error') return n
      const result = Math.abs(n.v)
      if (!isFiniteResult(result)) return errVal('#DIV/0!')
      return numVal(result)
    }

    if (name === 'IF') {
      if (node.args.length !== 3) return errVal('#ERR!')
      const condVals = this.expandArg(node.args[0])
      const condErr = condVals.find((v) => v.t === 'error')
      if (condErr) return condErr
      const cond = condVals[0]
      let b
      if (cond.t === 'bool') b = cond.v
      else if (cond.t === 'number') b = cond.v !== 0
      else return errVal('#VALUE!')
      const branch = b ? node.args[1] : node.args[2]
      const vals = this.expandArg(branch)
      const err = vals.find((v) => v.t === 'error')
      if (err) return err
      return vals[0]
    }

    // SUM, MIN, MAX, COUNT, AVG: one or more arguments
    if (node.args.length < 1) return errVal('#ERR!')
    const vals = this.expandArgs(node.args)
    const err = vals.find((v) => v.t === 'error')
    if (err) return err

    if (name === 'COUNT') {
      const count = vals.filter((v) => v.t === 'number').length
      return numVal(count)
    }

    // Convert each to number, left to right, first #VALUE! wins.
    const nums = []
    for (const v of vals) {
      const n = toNumber(v)
      if (n.t === 'error') return n
      nums.push(n.v)
    }

    let result
    if (name === 'SUM') {
      result = nums.reduce((a, b) => a + b, 0)
    } else if (name === 'MIN') {
      result = Math.min(...nums)
    } else if (name === 'MAX') {
      result = Math.max(...nums)
    } else if (name === 'AVG') {
      result = nums.reduce((a, b) => a + b, 0) / nums.length
    }
    if (!isFiniteResult(result)) return errVal('#DIV/0!')
    return numVal(result)
  }
}

function typeRank(v) {
  if (v.t === 'number') return 0
  if (v.t === 'text') return 1
  if (v.t === 'bool') return 2
  throw new Error('unreachable')
}

function compareValues(op, lv, rv) {
  let cmp
  if (lv.t === rv.t) {
    if (lv.t === 'number') cmp = lv.v - rv.v
    else if (lv.t === 'text') cmp = lv.v < rv.v ? -1 : lv.v > rv.v ? 1 : 0
    else cmp = (lv.v ? 1 : 0) - (rv.v ? 1 : 0)
  } else {
    cmp = typeRank(lv) - typeRank(rv)
  }
  let result
  switch (op) {
    case '=':
      result = cmp === 0
      break
    case '<>':
      result = cmp !== 0
      break
    case '<':
      result = cmp < 0
      break
    case '<=':
      result = cmp <= 0
      break
    case '>':
      result = cmp > 0
      break
    case '>=':
      result = cmp >= 0
      break
    default:
      throw new Error('unreachable op')
  }
  return boolVal(result)
}

/** Purely syntactic dependency extraction: every address named directly by
