/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { Evaluator, collectDeps } from './evaluator.js'
import { formatValue } from './value.js'
import { compareAddr } from './address.js'

function readStdin() {
  const fs = require_fs()
  return fs.readFileSync(0, 'utf8')
}

function require_fs() {
  // eslint-disable-next-line
  return globalThis.process.binding ? require('node:fs') : require('node:fs')
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      process.stderr.write(e.message + '\n')
      process.exit(2)
    }
    throw e
  }

  const addrs = Array.from(cells.keys()).sort(compareAddr)

  let out = ''
  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const addr of addrs) {
      const value = evaluator.evaluateCell(addr)
      out += `${addr}=${formatValue(value)}\n`
    }
  } else {
    for (const addr of addrs) {
      const deps = collectDeps(cells.get(addr))
      out += `${addr}:` + deps.map((d) => ` ${d}`).join('') + '\n'
    }
  }
  process.stdout.write(out)
  process.exit(0)
}

main()
"}

