function compareValues(op, lv, rv) {
  let cmp
  if (lv.t === rv.t) {
    if (lv.t === 'number') cmp = lv.v < rv.v ? -1 : lv.v > rv.v ? 1 : 0
    else if (lv.t === 'text') cmp = lv.v < rv.v ? -1 : lv.v > rv.v ? 1 : 0
    else {
      const a = lv.v ? 1 : 0
      const b = rv.v ? 1 : 0
      cmp = a < b ? -1 : a > b ? 1 : 0
    }
  } else {
    cmp = typeRank(lv) - typeRank(rv)
  }
